import Phaser from 'phaser';
import { ensureAnimations, playSpider } from '../visual/animations.js';

const WALK_SPEED = 250;
const CLIMB_SPEED = 150;
const JUMP_SPEED = -500;
const WEB_RANGE = 400;
const NORMAL_GRAVITY = 0;
const CEILING_LOCAL_GRAVITY = -2000;

/** Игрок-паук: Arcade gravity.y задаётся с учётом глобальной гравитации сцены. */
export default class Spider extends Phaser.Physics.Arcade.Sprite {
  constructor(scene, x, y, { solids } = {}) {
    ensureAnimations(scene);
    super(scene, x, y, 'jam-spider');
    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setDisplaySize(90, 90);
    this.setCollideWorldBounds(true);
    // Текстура fallback 512×512; body offset задаётся в координатах исходной текстуры.
    this.body.setSize(190, 148);
    this.body.setOffset(161, 182);
    this.body.setGravityY(NORMAL_GRAVITY);
    this.health = 100;
    this.ceilingAttached = false;
    this.solids = solids ?? null;
    this.webUnlocked = false;
    this.webAnchor = null;
    this._disposed = false;
    this._ownerScene = scene;
    this._lastStepAt = 0;
    this._webGraphics = scene.add.graphics().setDepth(20);
    this._collider = this.solids ? scene.physics.add.collider(this, this.solids) : null;

    const keyboard = scene.input.keyboard;
    this.keys = keyboard.addKeys({ left: 'A', right: 'D', up: 'W', down: 'S', jump: 'SPACE' });
    this._onPointerDown = (pointer) => {
      if (pointer.button === 0) this._tryAttachWeb(pointer);
    };
    this._onPointerUp = (pointer) => {
      if (pointer.button === 0 || pointer.button === undefined) this._releaseWeb();
    };
    scene.input.on('pointerdown', this._onPointerDown);
    scene.input.on('pointerup', this._onPointerUp);
    scene.input.on('gameout', this._onPointerUp);
  }

  setWebUnlocked(unlocked) {
    this.webUnlocked = Boolean(unlocked);
    if (!this.webUnlocked) this._releaseWeb();
  }

  takeDamage(amount) {
    const value = Number(amount);
    if (!Number.isFinite(value) || value <= 0 || this.health <= 0) return this.health;
    this.health = Math.max(0, this.health - value);
    return this.health;
  }

  update(time, delta) {
    if (!this.active || !this.body?.enable) return;
    const body = this.body;
    const left = this.keys.left.isDown;
    const right = this.keys.right.isDown;
    const horizontal = (right ? 1 : 0) - (left ? 1 : 0);
    const dt = Math.min(delta, 50) / 1000;

    const wallContact = body.blocked.left || body.blocked.right;
    body.setAllowGravity(this.ceilingAttached || !wallContact);
    body.setVelocityX(horizontal * WALK_SPEED);
    if (this.ceilingAttached) {
      body.setVelocityX(-horizontal * WALK_SPEED);
      if (this.keys.down.isDown) this._detachCeiling();
      else if (this.keys.up.isDown) body.setVelocityY(-CLIMB_SPEED);
      else body.setVelocityY(0);
    } else if (body.blocked.left || body.blocked.right) {
      if (this.keys.up.isDown) body.setVelocityY(-CLIMB_SPEED);
      else if (this.keys.down.isDown) body.setVelocityY(CLIMB_SPEED);
      else body.setVelocityY(0);
      if (this.keys.up.isDown || this.keys.down.isDown) {
        // Корпус ориентирован вдоль вертикальной поверхности; сторона контакта задаёт поворот.
        this.setAngle(body.blocked.left ? -90 : 90);
      } else {
        this.setAngle(0);
      }
    } else {
      body.setVelocityX(horizontal * WALK_SPEED);
      if (horizontal) this.setFlipX(horizontal < 0);
      this.setAngle(0);
      if (this.keys.jump.isDown && body.blocked.down) {
        body.setVelocityY(JUMP_SPEED);
        this._emit('jam:noise', { x: this.x, y: this.y, radius: 220 });
      }
      if (body.blocked.up && this.keys.up.isDown) this._attachCeiling();
    }

    // Arcade складывает body.gravity с world.gravity: -2000 локально даёт -1000 итог.
    if (!this.ceilingAttached && body.blocked.up && this.keys.up.isDown) this._attachCeiling();
    this._updateWeb(dt);

    const moving = Math.abs(body.velocity.x) > 5 || Math.abs(body.velocity.y) > 5;
    const mode = this.webAnchor ? 'web' : (body.blocked.down ? (moving ? 'walk' : 'idle') : 'jump');
    if (mode !== this._lastMode) {
      if (this._lastMode === 'walk' && mode !== 'walk') this._emit('jam:step', { actor: 'spider', x: this.x, y: this.y });
      this._lastMode = mode;
    }
    if (mode === 'walk' && time - this._lastStepAt >= 450) {
      this._lastStepAt = time;
      this._emit('jam:step', { actor: 'spider', x: this.x, y: this.y });
    }
    playSpider(this, mode, { speed: moving ? Math.hypot(body.velocity.x, body.velocity.y) : 0, turn: horizontal });
  }

  _attachCeiling() {
    this.ceilingAttached = true;
    this.body.setGravityY(CEILING_LOCAL_GRAVITY);
    this.body.setVelocityY(0);
    this.setFlipY(true);
  }

  _detachCeiling() {
    this.ceilingAttached = false;
    this.body.setAllowGravity(true).setGravityY(NORMAL_GRAVITY);
    this.body.setVelocityY(40);
    this.setFlipY(false);
    this._emit('jam:noise', { x: this.x, y: this.y, radius: 280 });
  }

  _tryAttachWeb(pointer) {
    if (!this.webUnlocked || this.webAnchor || !this.solids) return;
    const camera = this.scene.cameras.main;
    const target = camera.getWorldPoint(pointer.x, pointer.y);
    const dx = target.x - this.x;
    const dy = target.y - this.y;
    const distance = Math.hypot(dx, dy);
    if (!distance) return;
    const length = Math.min(WEB_RANGE, distance);
    const ux = dx / distance;
    const uy = dy / distance;
    let nearest = null;
    const children = this.solids.getChildren();
    for (const platform of children) {
      const rect = platform.getBounds?.();
      if (!rect) continue;
      const hit = segmentRectHit(this.x, this.y, ux, uy, length, rect);
      if (hit !== null && (nearest === null || hit < nearest)) nearest = hit;
    }
    if (nearest === null) return;
    this.webAnchor = { x: this.x + ux * nearest, y: this.y + uy * nearest, length: nearest };
    this._emit('jam:noise', { x: this.x, y: this.y, radius: 180 });
  }

  _updateWeb(dt) {
    const graphics = this._webGraphics;
    graphics.clear();
    if (!this.webAnchor) return;
    const anchor = this.webAnchor;
    const dx = this.x - anchor.x;
    const dy = this.y - anchor.y;
    const distance = Math.hypot(dx, dy) || 1;
    const nx = dx / distance;
    const ny = dy / distance;
    // Радиальное натяжение: не допускаем длину сверх исходной и убираем скорость наружу.
    if (distance > anchor.length) {
      const excess = distance - anchor.length;
      this.setPosition(this.x - nx * excess, this.y - ny * excess);
      const outward = this.body.velocity.x * nx + this.body.velocity.y * ny;
      if (outward > 0) {
        this.body.setVelocity(this.body.velocity.x - nx * outward, this.body.velocity.y - ny * outward);
      }
    }
    this.body.setAcceleration((anchor.x - this.x) * 2.2, (anchor.y - this.y) * 2.2);
    graphics.lineStyle(3, 0xc9d5d8, 0.8).beginPath().moveTo(anchor.x, anchor.y).lineTo(this.x, this.y).strokePath();
    if (dt === 0) this.body.setAcceleration(0, 0);
  }

  _releaseWeb() {
    this.webAnchor = null;
    this.body?.setAcceleration(0, 0);
    this._webGraphics?.clear();
  }

  _emit(event, payload) {
    this.scene?.game?.events?.emit(event, payload);
  }

  dispose() {
    if (this._disposed) return;
    this._disposed = true;
    const scene = this._ownerScene;
    scene.input.off('pointerdown', this._onPointerDown);
    scene.input.off('pointerup', this._onPointerUp);
    scene.input.off('gameout', this._onPointerUp);
    for (const key of Object.values(this.keys ?? {})) scene.input.keyboard.removeKey(key, true);
    this.webAnchor = null;
    if (this._webGraphics?.scene) this._webGraphics.destroy();
    if (this._collider) this._collider.destroy();
    this.destroy();
  }
}

// Первый вход луча в прямоугольник staticBody; возвращает расстояние либо null.
function segmentRectHit(x, y, ux, uy, maxDistance, rect) {
  let near = 0;
  let far = maxDistance;
  for (const [origin, direction, min, max] of [[x, ux, rect.left, rect.right], [y, uy, rect.top, rect.bottom]]) {
    if (Math.abs(direction) < 1e-8) {
      if (origin < min || origin > max) return null;
      continue;
    }
    let a = (min - origin) / direction;
    let b = (max - origin) / direction;
    if (a > b) [a, b] = [b, a];
    near = Math.max(near, a);
    far = Math.min(far, b);
    if (near > far) return null;
  }
  return near <= maxDistance ? near : null;
}

