const COLORS = Object.freeze({ panel: 0x071018, text: '#e8edf0', muted: '#9aabb4', accent: 0xc64646 });

/** Создаёт HUD Phaser и возвращает узкий интерфейс для публикации снимков. */
export function createHUD(scene, { onRestart = () => {}, onMenu = () => {} } = {}) {
  const root = scene.add.container(0, 0).setScrollFactor(0).setDepth(1000);
  const panel = scene.add.graphics();
  panel.fillStyle(COLORS.panel, 0.78).fillRoundedRect(28, 24, 420, 160, 12);
  root.add(panel);

  const title = text(52, 40, 'КАРАКУРТ · ВОЗМЕЗДИЕ', 17, '#d0d8dc');
  const progress = text(52, 68, '', 22, COLORS.text);
  const healthLabel = text(52, 106, 'ЗДОРОВЬЕ', 13, COLORS.muted);
  const healthTrack = scene.add.graphics();
  const act = text(52, 140, '', 15, COLORS.text);
  const attempt = text(284, 140, '', 15, COLORS.muted);
  const alert = text(284, 106, '', 13, COLORS.text);
  root.add([title, progress, healthLabel, healthTrack, act, attempt, alert]);

  const overlay = scene.add.rectangle(960, 540, 1920, 1080, 0x020508, 0.82).setScrollFactor(0);
  const message = text(960, 410, '', 42, '#f5eeee').setOrigin(0.5);
  const restartButton = makeButton(960, 540, 'ПОПРОБОВАТЬ СНОВА', () => onRestart());
  const menuButton = makeButton(960, 620, 'В ГЛАВНОЕ МЕНЮ', () => onMenu());
  overlay.setDepth(1001);
  message.setDepth(1002);
  restartButton.setDepth(1003);
  menuButton.setDepth(1003);
  root.add([overlay, message, restartButton, menuButton]);
  overlay.setVisible(false);
  message.setVisible(false);
  restartButton.setVisible(false);
  menuButton.setVisible(false);

  let destroyed = false;
  function setState(snapshot = {}) {
    if (destroyed || !snapshot) return;
    const actMemories = snapshot.act === 2 ? Math.max(0, snapshot.memories - 3) : snapshot.memories;
    progress.setText(`ПАМЯТЬ  ${actMemories || 0} / ${snapshot.target === 0 ? '—' : Number(snapshot.target) || 0}`);
    const health = Math.max(0, Math.min(100, Number(snapshot.health) || 0));
    healthTrack.clear().fillStyle(0x26343b, 1).fillRoundedRect(52, 126, 200, 9, 4);
    if (health > 0) healthTrack.fillStyle(health > 35 ? 0x82b5a1 : 0xc64646, 1).fillRoundedRect(52, 126, 200 * health / 100, 9, 4);
    act.setText(`АКТ ${snapshot.act ?? 1}`);
    attempt.setText(`ПОПЫТКА ${snapshot.attempt ?? 1}`);
    const alertNames = { PATROL: 'СПОКОЙНО', SUSPICION: 'ПОДОЗРЕНИЕ', CHASE: 'ТРЕВОГА · ПОГОНЯ' };
    alert.setText(`◉  ${alertNames[snapshot.alert] ?? alertNames.PATROL}`);
    alert.setColor(snapshot.alert === 'CHASE' ? '#ff6b61' : snapshot.alert === 'SUSPICION' ? '#e6c873' : COLORS.muted);
    const terminal = snapshot.status === 'dead' || snapshot.status === 'victory';
    overlay.setVisible(terminal);
    message.setText(snapshot.status === 'victory' ? 'Месть свершилась' : 'Вы были раздавлены');
    message.setVisible(terminal);
    restartButton.setVisible(terminal && snapshot.status === 'dead');
    menuButton.setVisible(terminal && snapshot.status === 'victory');
  }

  function makeButton(x, y, label, callback) {
    const background = scene.add.rectangle(x, y, 360, 54, 0x29343a, 1).setStrokeStyle(2, 0xb7c2c8).setInteractive({ useHandCursor: true });
    const caption = text(x, y, label, 17, '#ffffff').setOrigin(0.5);
    background.on('pointerover', () => background.setFillStyle(0x46555d));
    background.on('pointerout', () => background.setFillStyle(0x29343a));
    background.on('pointerdown', callback);
    return scene.add.container(0, 0, [background, caption]).setScrollFactor(0).setDepth(1001);
  }

  function text(x, y, value, size, color) {
    return scene.add.text(x, y, value, { fontFamily: 'Arial, sans-serif', fontSize: `${size}px`, color, fontStyle: 'bold' }).setScrollFactor(0);
  }

  return {
    setState,
    destroy() {
      if (destroyed) return;
      destroyed = true;
      root.destroy(true);
    },
  };
}

